// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
        // C casts LogFile = Log(_log) without a runtime code check, so a tiny
        // log stub is sufficient to make Put() usable in the reference.
        LogStub lg = new LogStub();
        c.SetLogFile(address(lg));
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 2 ** 100);
        lockTime = bound(lockTime, 0, 10 ** 12); // avoid timestamp overflow in Put

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        // move past the unlock time
        vm.warp(block.timestamp + lockTime + 1);

        vm.prank(actor);
        c.Collect(amount);

        // The recorded deposit must be withdrawable: after collecting the full
        // amount, the contract holds nothing. The mutant never records the
        // deposit, so Collect is a no-op and the contract still holds `amount`.
        assertTrue(address(c).balance == 0);
    }
}

contract LogStub {
    function AddMessage(address, uint256, string calldata) external pure {}
}
